CREATE TYPE outbox_status AS ENUM ('PENDING', 'PROCESSING', 'PROCESSED', 'DEAD_LETTERED');\n\nCREATE TABLE projection_outbox (\n  id                uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  tenant_id         uuid NOT NULL,\n  event_id          uuid NOT NULL,\n  aggregate_type    varchar(40) NOT NULL,\n  aggregate_id      uuid NOT NULL,\n  aggregate_version bigint NOT NULL,\n  event_type        varchar(60) NOT NULL,\n  payload           jsonb NOT NULL,\n  status            outbox_status NOT NULL DEFAULT 'PENDING',\n  attempts          smallint NOT NULL DEFAULT 0,\n  next_retry_at     timestamptz NOT NULL DEFAULT now(),\n  last_error        text,\n  created_at        timestamptz NOT NULL DEFAULT now(),\n  processed_at      timestamptz,\n  dead_lettered_at  timestamptz,\n  UNIQUE (tenant_id, event_id)\n);\nCREATE INDEX idx_outbox_claimable ON projection_outbox (next_retry_at)\n  WHERE status IN ('PENDING', 'PROCESSING');\nCREATE INDEX idx_outbox_dlq ON projection_outbox (dead_lettered_at)\n  WHERE status = 'DEAD_LETTERED';\n\n-- RLS en shared kernel + outbox + audit\nALTER TABLE tenant        ENABLE ROW LEVEL SECURITY;\nALTER TABLE project       ENABLE ROW LEVEL SECURITY;\nALTER TABLE party         ENABLE ROW LEVEL SECURITY;\nALTER TABLE party_role    ENABLE ROW LEVEL SECURITY;\nALTER TABLE site          ENABLE ROW LEVEL SECURITY;\nALTER TABLE contract      ENABLE ROW LEVEL SECURITY;\nALTER TABLE contract_party ENABLE ROW LEVEL SECURITY;\nALTER TABLE work_package  ENABLE ROW LEVEL SECURITY;\nALTER TABLE document      ENABLE ROW LEVEL SECURITY;\nALTER TABLE projection_outbox ENABLE ROW LEVEL SECURITY;\nALTER TABLE audit_event   ENABLE ROW LEVEL SECURITY;\n\n-- Políticas: por tenant. Nota: cuando app_user está conectado\n-- (NOSUPERUSER NOBYPASSRLS), se aplican. El init script creó app_user.\n-- Estas políticas se aplican a PUBLIC por default; ok.\nDO $$\nDECLARE t text;\nBEGIN\n  FOR t IN SELECT unnest(ARRAY[\n    'project','party','party_role','site','contract','contract_party',\n    'work_package','document','projection_outbox','audit_event'\n  ]) LOOP\n    EXECUTE format(\n      'CREATE POLICY ti_%I ON %I USING (tenant_id = current_setting(''app.tenant_id'')::uuid)',\n      t, t);\n  END LOOP;\nEND $$;\n\n-- En la tabla tenant solo exponemos el row del propio tenant\nCREATE POLICY ti_tenant ON tenant\n  USING (tenant_id = current_setting('app.tenant_id')::uuid);